const reqText = $input.first().json.body.requirementText || '';
const projectKey = $input.first().json.body.projectKey || 'PROJ';
const geminiKey = $input.first().json.body.geminiApiKey;

const systemInstruction = `Bạn là Senior Business Analyst và Scrum Master.
Hãy bóc tách yêu cầu phần mềm thành cấu trúc Epic -> User Story -> Sub-tasks.
BẮT BUỘC chỉ trả về JSON thuần túy theo định dạng sau:
{
  "epics": [
    {
      "summary": "Tên Epic",
      "description": "Mô tả ngắn gọn",
      "stories": [
        {
          "summary": "Tiêu đề Story",
          "description": "As a [role], I want [feature] so that [benefit]",
          "acceptanceCriteria": ["Tiêu chí 1", "Tiêu chí 2"],
          "storyPoints": 3,
          "priority": "High",
          "tasks": [
            { "summary": "Task kỹ thuật cụ thể", "type": "Sub-task", "estimatedHours": 4 }
          ]
        }
      ]
    }
  ]
}`;

return {
  json: {
    geminiKey,
    requestBody: {
      contents: [
        {
          role: "user",
          parts: [
            { text: `${systemInstruction}

YÊU CẦU NGHIỆP VỤ:
${reqText}` }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.2,
        responseMimeType: "application/json"
      }
    }
  }
};

const response = $input.first().json;
let rawText = response.candidates[0].content.parts[0].text;

// Làm sạch ký tự markdown
rawText = rawText.replace(/```json/gi, '').replace(/```/gi, '').trim();

const parsed = JSON.parse(rawText);
return {
  json: {
    success: true,
    data: parsed
  }
};
